const dateFormatter = new Intl.DateTimeFormat("ru-RU", {
  day: "2-digit",
  month: "short",
  year: "numeric",
});

const dateTimeFormatter = new Intl.DateTimeFormat("ru-RU", {
  day: "2-digit",
  month: "short",
  year: "numeric",
  hour: "2-digit",
  minute: "2-digit",
});

export function formatDate(value?: Date | string | null): string {
  if (!value) return "—";
  return dateFormatter.format(typeof value === "string" ? new Date(value) : value);
}

export function formatDateTime(value?: Date | string | null): string {
  if (!value) return "—";
  return dateTimeFormatter.format(typeof value === "string" ? new Date(value) : value);
}

export function daysBetween(from: Date | string, to: Date | string = new Date()): number {
  const a = typeof from === "string" ? new Date(from) : from;
  const b = typeof to === "string" ? new Date(to) : to;
  return Math.max(0, Math.round((+b - +a) / 86_400_000));
}

export function pluralDays(n: number): string {
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return `${n} день`;
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return `${n} дня`;
  return `${n} дней`;
}

export type DeadlineState = "none" | "ok" | "soon" | "overdue";

const ACTIVE_STATUSES = new Set(["review", "clarification", "in_work"]);

export function deadlineState(deadline?: Date | string | null, status?: string): DeadlineState {
  if (!deadline) return "none";
  if (status && !ACTIVE_STATUSES.has(status)) return "none";
  const days = Math.ceil((+new Date(deadline) - Date.now()) / 86_400_000);
  if (days < 0) return "overdue";
  if (days <= 1) return "soon";
  return "ok";
}

import { cache } from "react";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import { SignJWT, jwtVerify } from "jose";
import { prisma } from "./db";

const COOKIE_NAME = "otklik_session";
const MAX_AGE = 60 * 60 * 24 * 7;

function secretKey() {
  return new TextEncoder().encode(process.env.AUTH_SECRET ?? "otklik-dev-secret");
}

export async function createSession(userId: string) {
  const token = await new SignJWT({ sub: userId })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime(`${MAX_AGE}s`)
    .sign(secretKey());

  const store = await cookies();
  store.set(COOKIE_NAME, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: MAX_AGE,
  });
}

export async function destroySession() {
  const store = await cookies();
  store.delete(COOKIE_NAME);
}

export const getCurrentUser = cache(async () => {
  const store = await cookies();
  const token = store.get(COOKIE_NAME)?.value;
  if (!token) return null;

  try {
    const { payload } = await jwtVerify(token, secretKey());
    const userId = typeof payload.sub === "string" ? payload.sub : null;
    if (!userId) return null;

    return await prisma.user.findUnique({
      where: { id: userId },
      include: { department: true, headed: true },
    });
  } catch {
    return null;
  }
});

export async function requireUser() {
  const user = await getCurrentUser();
  if (!user) redirect("/login");
  return user;
}

export async function requireAdmin() {
  const user = await requireUser();
  if (user.role !== "admin") redirect("/appeals");
  return user;
}

export type CurrentUser = NonNullable<Awaited<ReturnType<typeof getCurrentUser>>>;

import type { Prisma, User } from "@prisma/client";
import { prisma } from "./db";

export type ListFilters = {
  status?: string;
  categoryId?: string;
  departmentId?: string;
  type?: string;
  priority?: string;
  q?: string;
  overdue?: boolean;
};

export const appealListInclude = {
  category: true,
  department: true,
  author: true,
  assignee: true,
  responsible: true,
} satisfies Prisma.AppealInclude;

export type AppealListItem = Prisma.AppealGetPayload<{ include: typeof appealListInclude }>;

type ScopedUser = Pick<User, "id" | "role" | "departmentId">;

export function visibleWhere(user: ScopedUser): Prisma.AppealWhereInput {
  if (user.role === "admin") return {};
  if (user.role === "head" && user.departmentId) {
    return {
      OR: [
        { departmentId: user.departmentId },
        { authorId: user.id },
        { assigneeId: user.id },
        { subscriptions: { some: { userId: user.id } } },
      ],
    };
  }
  return {
    OR: [
      { authorId: user.id },
      { assigneeId: user.id },
      { subscriptions: { some: { userId: user.id } } },
    ],
  };
}

export function buildListWhere(user: ScopedUser, filters: ListFilters): Prisma.AppealWhereInput {
  const and: Prisma.AppealWhereInput[] = [visibleWhere(user)];

  if (filters.status) and.push({ status: filters.status });
  if (filters.categoryId) and.push({ categoryId: filters.categoryId });
  if (filters.departmentId) and.push({ departmentId: filters.departmentId });
  if (filters.type) and.push({ type: filters.type });
  if (filters.priority) and.push({ priority: filters.priority });

  if (filters.overdue) {
    and.push({
      deadline: { lt: new Date() },
      status: { in: ["review", "clarification", "in_work"] },
    });
  }

  if (filters.q) {
    const q = filters.q.trim();
    if (q) {
      and.push({
        OR: [
          { code: { contains: q } },
          { text: { contains: q } },
          { proposal: { contains: q } },
        ],
      });
    }
  }

  return { AND: and };
}

export async function listAppeals(user: ScopedUser, filters: ListFilters): Promise<AppealListItem[]> {
  return prisma.appeal.findMany({
    where: buildListWhere(user, filters),
    include: appealListInclude,
    orderBy: [{ createdAt: "desc" }],
    take: 200,
  });
}

export async function getAppealForUser(id: string, user: ScopedUser) {
  return prisma.appeal.findFirst({
    where: { AND: [{ id }, visibleWhere(user)] },
    include: {
      ...appealListInclude,
      duplicateOf: { select: { id: true, code: true } },
      duplicates: { select: { id: true, code: true } },
      attachments: true,
      comments: {
        include: { author: true },
        orderBy: { createdAt: "asc" },
      },
      history: {
        include: { actor: true },
        orderBy: { createdAt: "asc" },
      },
      rating: true,
    },
  });
}

export type AppealDetail = NonNullable<Awaited<ReturnType<typeof getAppealForUser>>>;

export function parseFilters(params: Record<string, string | string[] | undefined>): ListFilters {
  const value = (key: string) => {
    const raw = params[key];
    return typeof raw === "string" ? raw : "";
  };

  return {
    status: value("status") || undefined,
    categoryId: value("categoryId") || undefined,
    departmentId: value("departmentId") || undefined,
    type: value("type") || undefined,
    priority: value("priority") || undefined,
    q: value("q") || undefined,
    overdue: value("overdue") === "1",
  };
}

