const path = process.argv[2];
const { DatabaseSync } = require("node:sqlite");
const db = new DatabaseSync(path, { readOnly: true });
const tables = db
  .prepare("select name, sql from sqlite_master where type='table' order by name")
  .all();
for (const t of tables) {
  let count = "?";
  try {
    count = db.prepare(`select count(*) as c from "${t.name}"`).get().c;
  } catch {}
  console.log(`\n### ${t.name} (rows: ${count})`);
  console.log(t.sql);
}

const fs = require("node:fs");
const { DatabaseSync } = require("node:sqlite");
const p = process.env.CHAT_DB;
console.log("env:", JSON.stringify(p));
console.log("exists:", fs.existsSync(p));
console.log("dir:", fs.existsSync(require("node:path").dirname(p)));
try {
  const db = new DatabaseSync(p);
  console.log("opened rw");
  console.log(db.prepare("select count(*) as c from sqlite_master").get());
} catch (e) {
  console.log("open failed:", e.message, e.errcode);
}

const { DatabaseSync } = require("node:sqlite");
const db = new DatabaseSync(process.env.CHAT_DB, { readOnly: true });
const s = db.prepare("select * from session_v2").all();
console.log("SESSIONS:", JSON.stringify(s, null, 1).slice(0, 1500));
const msgs = db
  .prepare("select id, type, seq, time_created, data from session_message order by seq asc")
  .all();
console.log("MESSAGES:", msgs.length);
for (const m of msgs.slice(0, 3)) {
  console.log("\n---", m.seq, m.type, m.id, new Date(m.time_created).toISOString());
  console.log(m.data.slice(0, 2000));
}

const { DatabaseSync } = require("node:sqlite");
const db = new DatabaseSync(process.env.CHAT_DB, { readOnly: true });
const rows = db
  .prepare("select id, type, seq, time_created, length(data) as len, data from session_message order by seq asc")
  .all();
console.log("rows:", rows.length, "total bytes:", rows.reduce((a, r) => a + r.len, 0));
const byType = {};
for (const r of rows) byType[r.type] = (byType[r.type] || 0) + 1;
console.log("types:", byType);

const seen = {};
for (const r of rows) {
  const d = JSON.parse(r.data);
  const key =
    r.type +
    ":" +
    (Array.isArray(d.content) ? d.content.map((c) => c.type).join(",") : Object.keys(d).join(","));
  if (seen[key]) continue;
  seen[key] = 1;
  console.log("\n=== sample", r.seq, r.type, "size", r.len, "==");
  console.log(JSON.stringify(d, null, 1).slice(0, 2500));
}

