const { DatabaseSync } = require("node:sqlite");
const db = new DatabaseSync(process.env.CHAT_DB, { readOnly: true });
const rows = db
  .prepare("select seq, type, time_created, data from session_message order by seq asc")
  .all();
for (const r of rows) {
  const d = JSON.parse(r.data);
  if (r.type === "user") {
    console.log(`\n=== USER seq=${r.seq} ${new Date(r.time_created).toISOString()}`);
    console.log(d.text);
  }
  if (r.type === "compaction") {
    console.log(`\n=== COMPACTION seq=${r.seq} ${new Date(r.time_created).toISOString()} keep=${d.metadata && d.metadata.keepID}`);
    console.log((d.summary || "").slice(0, 400));
